import * as d3 from 'd3';

export const renderEnergyEndUseGraph = (chartRef, selectedFeatures, dashboardConfig) => {
  if (!chartRef?.current) {
    console.error("chartRef is null or undefined:", chartRef);
    return;
  }

  if (!Array.isArray(selectedFeatures)) {
    console.error("selectedFeatures is not an array:", selectedFeatures);
    return;
  }

  const filteredFeatures = selectedFeatures.filter(
    (feature) => feature?.geometry?.type !== 'Point'
  );

  const energyCategories = [
    "gasEquipment",
    "equipment",
    "lighting",
    "hotWater",
    "auxiliary",
    "cooling",
    "heating"
  ];

  const monthlyData = Array.from({ length: 12 }, () =>
    Object.fromEntries(energyCategories.map(category => [category, 0]))
  );

  filteredFeatures.forEach((feature) => {
    energyCategories.forEach((category) => {
      const propertyKey = {
        gasEquipment: "GasEquipment[KWh][Mth]",
        equipment: "Equipment[KWh][Mth]",
        lighting: "Lighting[KWh][Mth]",
        hotWater: "HotWater[KWh][Mth]",
        auxiliary: "Auxiliary[KWh][Mth]",
        cooling: "Cooling[KWh][Mth]",
        heating: "Heating[KWh][Mth]",
      }[category];

      const values = feature?.properties?.[propertyKey] || [];

      for (let month = 0; month < 12; month++) {
        monthlyData[month][category] += values[month] || 0;
      }
    });
  });

  // Ensure `keys` maintain order from `energyCategories`
  const keys = energyCategories.filter(category =>
    monthlyData.some(month => month[category] > 0)
  );

  if (!keys.length) {
    console.error("No valid keys found for monthlyData:", monthlyData);
    return;
  }

  const margin = { top: 10, right: 30, bottom: 100, left: 50 };
  const width = (dashboardConfig?.chartSettings?.width || 700) / 2 - margin.left - margin.right;
  const height = (dashboardConfig?.chartSettings?.height || 250) - margin.top - margin.bottom;

  const svg = d3.select(chartRef.current)
    .append('svg')
    .attr('width', width + margin.left + margin.right)
    .attr('height', height + margin.top + margin.bottom)
    .append('g')
    .attr('transform', `translate(${margin.left},${margin.top})`);

  const x = d3.scaleBand()
    .domain(d3.range(12))
    .range([0, width])
    .padding(0.1);

  const y = d3.scaleLinear()
    .domain([0, d3.max(monthlyData, d => keys.reduce((sum, key) => sum + d[key], 0))])
    .nice()
    .range([height, 0]);

  const colorScale = d3.scaleOrdinal()
    .domain(energyCategories) // Keep fixed order to avoid mismatching
    .range(['#D28066', '#959595', '#F2E75C', '#EEC176', '#B087D6', '#6FAADD', '#CF5867']);

  svg.selectAll('g.layer')
    .data(d3.stack().keys(keys)(monthlyData))
    .enter().append('g')
    .attr('class', 'layer')
    .attr('fill', d => colorScale(d.key))
    .selectAll('rect')
    .data(d => d)
    .enter().append('rect')
    .attr('x', (d, i) => x(i))
    .attr('y', d => y(d[1]))
    .attr('height', d => y(d[0]) - y(d[1]))
    .attr('width', x.bandwidth());

  svg.append('g')
    .attr('class', 'x-axis')
    .attr('transform', `translate(0,${height})`)
    .call(d3.axisBottom(x).tickFormat((i) => i + 1));

  svg.append('g')
    .attr('class', 'y-axis')
    .call(d3.axisLeft(y).ticks(5).tickFormat(d3.format('.2s')));

  const legend = svg.append('g')
    .attr('transform', `translate(0, ${height + 30})`);

  keys.forEach((category, i) => {
    const row = Math.floor(i / 3);
    const col = i % 3;

    legend.append('rect')
      .attr('x', col * 105)
      .attr('y', row * 20)
      .attr('width', 10)
      .attr('height', 10)
      .attr('fill', colorScale(category));

    legend.append('text')
      .attr('x', col * 105 + 15)
      .attr('y', row * 20 + 10)
      .text(category)
      .style('font-size', '12px')
      .style('fill', '#000');
  });
};
