import * as d3 from 'd3';

export const renderDonutGraph = (data, chartRef, dashboardConfig) => {
  // Check if the data contains categorical values
  const categoricalData = data.filter(d => typeof d === 'string' || isNaN(d));

  // If no categorical data is found, display a message instead of an empty graph
  if (categoricalData.length === 0) {
    d3.select(chartRef.current).selectAll('*').remove();
    d3.select(chartRef.current)
      .append('div')
      .style('text-align', 'center')
      .style('font-size', '14px')
      .style('color', '#d9534f') // Red text for emphasis
      .style('margin-top', '20px')
      .text("Data input not suitable for donut graph, please try other visualizations or switch to another selected proerty.");
    return;
  }

  const margin = { top: 20, right: 30, bottom: 40, left: 50 };
  const width = (dashboardConfig?.chartSettings?.width || 700) / 2;
  const height = (dashboardConfig?.chartSettings?.height || 250);
  const radius = Math.min(width, height) / 2 - 10;

  // Clear any existing content
  d3.select(chartRef.current).selectAll('*').remove();

  const svg = d3.select(chartRef.current)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .append('g')
    .attr('transform', `translate(${width / 2},${height / 2})`);

  // Count occurrences of each category
  const categoryCounts = categoricalData.reduce((acc, category) => {
    acc[category] = (acc[category] || 0) + 1;
    return acc;
  }, {});

  const pieData = Object.entries(categoryCounts).map(([key, value]) => ({
    category: key,
    count: value
  }));

  // Define pie and arc generators
  const pie = d3.pie().value(d => d.count);
  const arc = d3.arc().innerRadius(radius * 0.6).outerRadius(radius);

  // Define a low-saturation color scale
  const color = d3.scaleOrdinal(d3.schemeObservable10)
    .domain(pieData.map(d => d.category));

  // Draw the arcs
  const slices = svg.selectAll('path')
    .data(pie(pieData))
    .enter()
    .append('path')
    .attr('d', arc)
    .attr('fill', d => color(d.data.category))
    .attr('stroke', '#fff')
    .style('stroke-width', '2px')
    .on("mouseover", function(event, d) {
      centerText.text(`"${d.data.category}"`)
      .style("font-size", "14px")
        .append("tspan")
        .attr("x", 0)
        .attr("dy", "1.2em")
        .attr("font-size", "12px")
        .text(`${d.data.count}`);
    })
    .on("mouseout", function() {
      centerText.text("Hover to see details");
      centerText.style("font-size", "10px")

    });

  // Center text (default message)
  const centerText = svg.append("text")
    .attr("text-anchor", "middle")
    .attr("dy", "0.35em")
    .style("font-size", "12px")
    .style("fill", "#666")
    .text("Hover to see details");
};
