import * as d3 from 'd3';

export const renderEnergyNetUpfrontCostGraph = (chartRef, selectedFeatures, dashboardConfig) => {

  if (!Array.isArray(selectedFeatures)) {
    console.error("selectedFeatures is not an array:", selectedFeatures);
    return;
  }

  const filteredFeatures = selectedFeatures.filter(
    (feature) => feature.geometry?.type !== 'Point'
  );

  const annualData = {
    totalUpgradeCost: 0,
    netUpfrontCost: 0,
  };

  filteredFeatures.forEach((feature) => {
    annualData.totalUpgradeCost += feature.properties?.["TotalUpgradeCost[$]"] || 0;
    annualData.netUpfrontCost += feature.properties?.["NetUpfrontCost[$]"] || 0;
  });

  const totalUpgradeCost = annualData.totalUpgradeCost;
  const netUpfrontCost = annualData.netUpfrontCost;

  if (totalUpgradeCost === 0) {
    console.error("Total upgrade cost is zero, cannot render graph.");
    return;
  }

  const netCostPercentage = ((netUpfrontCost / totalUpgradeCost) * 100).toFixed(1);

  const margin = { top: 20, right: 40, bottom: 90, left: 20 };
  const width = (dashboardConfig?.chartSettings?.width || 700) / 2 - margin.left - margin.right;
  const height = dashboardConfig?.chartSettings?.height || 70;

  const svg = d3.select(chartRef.current)
    .append('svg')
    .attr('width', width + margin.left + margin.right)
    .attr('height', height + margin.top + margin.bottom)
    .append('g')
    .attr('transform', `translate(${margin.left},${margin.top})`);

  const x = d3.scaleLinear()
    .domain([0, totalUpgradeCost])
    .nice()
    .range([0, width]);

  const y = d3.scaleBand()
    .range([0, height])
    .padding(0.1);

  // New color scheme: total cost is orange, net upfront cost is blue
  const colorScale = {
    totalUpgradeCost: '#FFA726', // Orange
    netUpfrontCost: '#42A5F5',  // Blue
  };

  // Render total upgrade cost bar
  svg.append('rect')
    .attr('x', 0)
    .attr('y', 0)
    .attr('height', y.bandwidth() || height)
    .attr('width', x(totalUpgradeCost))
    .attr('fill', colorScale.totalUpgradeCost);

  // Render net upfront cost bar (overlapping on top of total cost)
  svg.append('rect')
    .attr('x', 0)
    .attr('y', 0)
    .attr('height', y.bandwidth() || height)
    .attr('width', x(netUpfrontCost))
    .attr('fill', colorScale.netUpfrontCost);

  // Add label for total upgrade cost
  svg.append('text')
    .attr('x', x(totalUpgradeCost) - 5)
    .attr('y', height / 2)
    .attr('dy', '.35em')
    .style('font-size', '12px')
    .style('fill', '#000')
    .style('text-anchor', 'end')
    .text(`$${d3.format('.2s')(totalUpgradeCost)}`);

  // Net upfront cost value
  svg.append('text')
    .attr('x', x(netUpfrontCost) - 5)
    .attr('y', height / 2 - 5) // Center vertically for the number
    .attr('dy', '.35em')
    .style('font-size', '12px')
    .style('fill', '#FFF')
    .style('text-anchor', 'end')
    .text(`$${d3.format('.2s')(netUpfrontCost)}`);

  // Net upfront cost percentage
  svg.append('text')
    .attr('x', x(netUpfrontCost) - 5)
    .attr('y', height / 2 + 10) // Slightly below the number
    .attr('dy', '.35em')
    .style('font-size', '10px')
    .style('fill', '#FFF')
    .style('text-anchor', 'end')
    .text(`(${netCostPercentage}%)`);


  // X-axis
  svg.append('g')
    .attr('class', 'x-axis')
    .attr('transform', `translate(0,${height})`)
    .call(d3.axisBottom(x).ticks(5).tickFormat(d3.format('.2s')));

  svg.selectAll('.x-axis text')
    .style('font-size', '10px')
    .style('fill', '#000');

  svg.append("text")
    .attr("class", "x-axis-label")
    .attr("x", width)
    .attr("y", height + 30)
    .attr("text-anchor", "middle")
    .style("font-size", "10px")
    .text("$");

  // Legend
  const legend = svg.append('g')
    .attr('transform', `translate(0, ${height + 30})`);

  const categories = ['totalUpgradeCost', 'netUpfrontCost'];
  categories.forEach((category, i) => {
    legend.append('rect')
      .attr('x', i * 150)
      .attr('y', 0)
      .attr('width', 10)
      .attr('height', 10)
      .attr('fill', colorScale[category]);

    legend.append('text')
      .attr('x', i * 150 + 20)
      .attr('y', 10)
      .text(category === 'totalUpgradeCost' ? 'Total Upgrade Cost' : 'Net Upfront Cost')
      .style('font-size', '12px')
      .style('fill', '#000');
  });
};
