import React, { useState, useEffect } from 'react';
import { Paper } from '@mui/material';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

const DockableCard = ({ 
  children, 
  width = '420px',
  priority = 'normal',
  onCollapsedChange = () => {},
  isMobileView = false,
  containerWidth = 420
}) => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isActive, setIsActive] = useState(false);
  const [scale, setScale] = useState(1);

  useEffect(() => {
    if (isMobileView) {
      // Calculate scale based on container width vs original width
      const originalWidth = 400; // Our base width
      const newScale = (containerWidth) / originalWidth;
      setScale(newScale);
    } else {
      setScale(1);
    }
  }, [isMobileView, containerWidth]);

  const getBaseZIndex = () => {
    return priority === 'high' ? 2000 : 1000;
  };

  return (
    <div 
      style={{ 
        position: 'relative',
        perspective: '1000px',
        marginBottom: isCollapsed ? '0px' : '20px',
        transition: 'margin 0.4s ease',
        width: '100%',
      }}
    >
      {/* Custom Fab button */}
      <div 
        onClick={() => setIsCollapsed(!isCollapsed)}
        style={{
          position: 'absolute',
          top: isCollapsed ? '-10px' : '-12px',
          left: '50%',
          transform: `translateX(-50%) scale(${isCollapsed ? 0.85 : 1})`,
          zIndex: getBaseZIndex() + 1,
          backgroundColor: 'white',
          width: '32px',
          height: '24px',
          borderRadius: '16px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          boxShadow: '0 2px 5px rgba(0,0,0,0.2)',
          transition: 'all 0.3s ease',
        }}
      >
        {isCollapsed ? (
          <ExpandMoreIcon style={{ fontSize: '20px' }} />
        ) : (
          <ExpandLessIcon style={{ fontSize: '20px' }} />
        )}
      </div>

      {/* Card container */}
      <Paper
        elevation={3}
        onMouseEnter={() => setIsActive(true)}
        onMouseLeave={() => setIsActive(false)}
        onClick={() => setIsActive(true)}
        style={{
          width: '100%',
          backgroundColor: 'white',
          marginTop: isCollapsed ? '0px' : '20px',
          height: isCollapsed ? '30px' : 'auto',
          transition: 'all 0.4s ease',
          zIndex: getBaseZIndex() + (isActive ? 100 : 0),
        }}
      >
        {/* Content wrapper with folding animation and scaling */}
        <div
          style={{
            padding: '20px',
            transformOrigin: 'top',
            transform: `${isCollapsed ? 'rotateX(-90deg)' : 'rotateX(0)'} scale(${scale})`,
            opacity: isCollapsed ? 0 : 1,
            transition: 'all 0.4s ease',
            height: isCollapsed ? 0 : 'auto',
            overflow: 'hidden',
            transformStyle: 'preserve-3d',
          }}
        >
          <div style={{
            // Wrapper to maintain content proportions
            transformOrigin: 'top left',
            width: isMobileView ? `${100/scale}%` : '100%',
          }}>
            {children}
          </div>
        </div>
      </Paper>
    </div>
  );
};

export default DockableCard;