import React, { useState } from "react";
import {
  Paper,
  TextField,
  Button,
  Typography,
  Box,
  IconButton,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  Snackbar,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import DeleteIcon from "@mui/icons-material/Delete";

// Tile bounds calculation helper functions
function tileToLngLatBounds(x, y, z) {
  const n = Math.PI - (2 * Math.PI * y) / Math.pow(2, z);
  const n1 = Math.PI - (2 * Math.PI * (y + 1)) / Math.pow(2, z);

  const lon1 = (x / Math.pow(2, z)) * 360 - 180;
  const lon2 = ((x + 1) / Math.pow(2, z)) * 360 - 180;

  const lat1 = (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
  const lat2 =
    (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n1) - Math.exp(-n1)));

  return {
    north: Math.max(lat1, lat2),
    south: Math.min(lat1, lat2),
    east: Math.max(lon1, lon2),
    west: Math.min(lon1, lon2),
  };
}

function parseTileUrl(url) {
  const match = url.match(/\/(\d+)\/(\d+)\/(\d+)\./);
  if (match) {
    return {
      z: parseInt(match[1], 10),
      x: parseInt(match[2], 10),
      y: parseInt(match[3], 10),
    };
  }
  return null;
}

function calculateTileBounds(tileCoords) {
  const { x, y, z } = tileCoords;

  // Get bounds for the specific tile
  const bounds = tileToLngLatBounds(x, y, z);

  // Add some padding (e.g., include neighboring tiles)
  const padding = 10; // Number of tiles to pad
  const expandedBounds = {
    north: bounds.north + (bounds.north - bounds.south) * padding,
    south: bounds.south - (bounds.north - bounds.south) * padding,
    east: bounds.east + (bounds.east - bounds.west) * padding,
    west: bounds.west - (bounds.east - bounds.west) * padding,
  };

  return expandedBounds;
}

function calculateZoomLevel(bounds) {
  const { north, south, east, west } = bounds;
  const latDiff = north - south;
  const lonDiff = east - west;
  const maxDiff = Math.max(latDiff, lonDiff);

  // Rough estimation of appropriate zoom level
  const zoom = Math.floor(Math.log2(360 / maxDiff));

  // Clamp zoom level to reasonable bounds
  return Math.min(Math.max(zoom, 1), 18);
}

// Connection tester component
const TileConnectionTester = ({ tileTemplate }) => {
  const [testStatus, setTestStatus] = useState({ status: "idle" });

  const testConnection = async () => {
    try {
      setTestStatus({ status: "testing" });

      // Try to fetch a test tile
      const testTileUrl = tileTemplate
        .replace("{z}", "1")
        .replace("{x}", "1")
        .replace("{y}", "1");

      const response = await fetch(testTileUrl);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const contentType = response.headers.get("content-type");
      const data = await response.arrayBuffer();

      setTestStatus({
        status: "success",
        contentType,
        dataSize: data.byteLength,
      });
    } catch (error) {
      setTestStatus({
        status: "error",
        error: error.message,
      });
    }
  };

  React.useEffect(() => {
    if (tileTemplate) {
      testConnection();
    }
  }, [tileTemplate]);

  return (
    <Box mt={2}>
      <Typography variant="subtitle2" gutterBottom>
        Connection Status:
      </Typography>

      {testStatus.status === "testing" && (
        <Box display="flex" alignItems="center" gap={1}>
          <CircularProgress size={16} />
          <Typography>Testing connection...</Typography>
        </Box>
      )}

      {testStatus.status === "success" && (
        <Box>
          <Typography color="success.main">✓ Connected successfully</Typography>
          <Typography variant="caption" display="block">
            Content Type: {testStatus.contentType}
          </Typography>
          <Typography variant="caption" display="block">
            Data Size: {testStatus.dataSize} bytes
          </Typography>
        </Box>
      )}

      {testStatus.status === "error" && (
        <Typography color="error">
          ✗ Connection failed: {testStatus.error}
        </Typography>
      )}
    </Box>
  );
};

// Main ConnectCard component
const ConnectCard = ({
  onClose,
  setGeoJsonFilesByDashboard,
  setInitialSelection,
  setIsAppInitialized,
  config,
  setTileLayers,
  setConfig,
  setScenarioData,
  onTileServerConnected,
}) => {
  const [url, setUrl] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [connectedLayers, setConnectedLayers] = useState([]);
  const [snackbarMessage, setSnackbarMessage] = useState("");

  const showSnackbar = (message) => {
    setSnackbarMessage(message);
  };

  const parseTileUrlTemplate = (url) => {
    if (url.includes("{z}") && url.includes("{x}") && url.includes("{y}")) {
      return url.endsWith(".geojson") ? url.replace(".geojson", ".mvt") : url;
    }

    const regex = /(.*\/)[0-9]+\/[0-9]+\/[0-9]+\.(geojson|mvt)$/;
    const match = url.match(regex);
    if (match && match[1]) {
      return `${match[1]}{z}/{x}/{y}.mvt`;
    }

    let baseUrl = url;
    if (!baseUrl.endsWith("/")) {
      baseUrl += "/";
    }
    return `${baseUrl}{z}/{x}/{y}.mvt`;
  };

  const handleAddLayer = async () => {
    setIsLoading(true);
    setError("");

    try {
      const layerName =
        url.split("/").slice(-4, -3)[0] ||
        `Layer ${connectedLayers.length + 1}`;

      const tileTemplate = parseTileUrlTemplate(url);
      const minZoom = 0;
      const maxZoom = 22;

      // Extract x, y, z from the URL if provided
      const tileCoords = parseTileUrl(url);
      let defaultCenter = [0, 0];
      let defaultZoom = 2;
      let bounds;

      if (tileCoords) {
        bounds = calculateTileBounds(tileCoords);
        defaultZoom = calculateZoomLevel(bounds);
        defaultCenter = [
          (bounds.east + bounds.west) / 2,
          (bounds.north + bounds.south) / 2,
        ];
      }

      const newLayer = {
        name: layerName,
        tileTemplate,
        minZoom,
        maxZoom,
        defaultCenter,
        defaultZoom,
        bounds,
      };

      setConnectedLayers((prevLayers) => [...prevLayers, newLayer]);
      setTileLayers((prev) => [...prev, newLayer]);
      setUrl("");
      showSnackbar(`Successfully added layer: ${layerName}`);
    } catch (err) {
      setError("Failed to connect to tile server: " + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRemoveLayer = (index) => {
    setConnectedLayers((prev) => prev.filter((_, i) => i !== index));
  };

  // Add these functions to ConnectCard.jsx
  function calculateDefaultBounds(template) {
    // Default bounds for Ithaca, NY area as an example
    // You can adjust these coordinates based on your needs
    const defaultBounds = {
      west: -76.5369,
      south: 42.4195,
      east: -76.471,
      north: 42.4735,
    };
    return defaultBounds;
  }

  function getInitialBounds(tileTemplate) {
    // First try to parse explicit tile coordinates
    const tileMatch = tileTemplate.match(/\/(\d+)\/(\d+)\/(\d+)\./);
    if (tileMatch) {
      const [_, z, x, y] = tileMatch.map(Number);
      return calculateTileBounds({ z, x, y });
    }

    // If no explicit coordinates, return default bounds
    return calculateDefaultBounds(tileTemplate);
  }

  const handleConnect = async () => {
    if (connectedLayers.length === 0) {
      setError("Please add at least one layer before connecting");
      return;
    }

    setIsLoading(true);

    try {
      // Create a virtual GeoJSON file for each connected layer
      const virtualGeoJsonFiles = connectedLayers.map((layer) => ({
        name: layer.name,
        data: {
          type: "FeatureCollection",
          features: [],
          tileSource: {
            type: "vector",
            tiles: [layer.tileTemplate],
            minzoom: layer.minZoom || 0,
            maxzoom: layer.maxZoom || 22,
            bounds: layer.bounds
              ? [
                  layer.bounds.west,
                  layer.bounds.south,
                  layer.bounds.east,
                  layer.bounds.north,
                ]
              : undefined,
          },
        },
      }));

      // Update geoJsonFilesByDashboard with the virtual files
      setGeoJsonFilesByDashboard({
        DataDashboard: virtualGeoJsonFiles,
      });

      // Calculate view bounds from the first layer
      const firstLayer = connectedLayers[0];
      const bounds = getInitialBounds(firstLayer.tileTemplate);
      const defaultView = {
        bounds: bounds,
        zoom: calculateZoomLevel(bounds),
        center: [
          (bounds.east + bounds.west) / 2,
          (bounds.north + bounds.south) / 2,
        ],
      };

      // Create initial selection
      setInitialSelection({
        dashboard: "DataDashboard",
        scenario: virtualGeoJsonFiles[0].data,
        selectedProperty: null,
        defaultView,
      });

      // Update config to ensure DataDashboard has necessary settings
      setConfig((prevConfig) => ({
        ...prevConfig,
        DataDashboard: {
          ...prevConfig.DataDashboard,
          tiledData: true,
          scenarioText: "Connected Tile Layers",
          properties: [...(prevConfig.DataDashboard?.properties || [])],
        },
      }));

      // Update scenario data if needed
      setScenarioData((prevData) => ({
        ...prevData,
        DataDashboard_Scenario1: {}, // Initialize empty scenario data
      }));

      setIsAppInitialized(true);
      onClose();
      setTileLayers(connectedLayers);

      // Notify parent component about new virtual files
      if (onTileServerConnected) {
        onTileServerConnected(virtualGeoJsonFiles);
      }
    } catch (error) {
      console.error("[DEBUG] Error in handleConnect:", error);
      setError("Failed to initialize layers: " + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      <Paper
        elevation={3}
        style={{
          padding: "20px",
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "600px",
          maxHeight: "80vh",
          overflow: "auto",
          zIndex: 1000,
        }}
      >
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={2}
        >
          <Typography variant="h6">Connect to Tile Server</Typography>
          <IconButton onClick={onClose}>
            <CloseIcon />
          </IconButton>
        </Box>

        <Typography variant="body2" mb={2}>
          Enter the URL of a tile from your tile server. You can add multiple
          layers that will appear as scenarios in the viewer.
        </Typography>

        <Box mb={3}>
          <TextField
            fullWidth
            label="Tile Server URL"
            variant="outlined"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            placeholder="https://example.com/tiles/{z}/{x}/{y}.mvt"
            error={!!error}
            helperText={error}
            sx={{ mb: 1 }}
          />
          <TileConnectionTester tileTemplate={url} />
          <Button
            variant="contained"
            onClick={handleAddLayer}
            disabled={!url || isLoading}
            size="small"
          >
            Add Layer
          </Button>
        </Box>

        {connectedLayers.length > 0 && (
          <Box mb={3}>
            <Typography variant="subtitle2" mb={1}>
              Connected Layers
            </Typography>
            <List>
              {connectedLayers.map((layer, index) => (
                <ListItem key={index} divider>
                  <ListItemText
                    primary={layer.name}
                    secondary={`Zoom levels: ${layer.minZoom}-${layer.maxZoom}`}
                  />
                  <ListItemSecondaryAction>
                    <IconButton
                      edge="end"
                      onClick={() => handleRemoveLayer(index)}
                      size="small"
                    >
                      <DeleteIcon />
                    </IconButton>
                  </ListItemSecondaryAction>
                </ListItem>
              ))}
            </List>
          </Box>
        )}

        <Box display="flex" justifyContent="flex-end" gap={1}>
          <Button variant="outlined" onClick={onClose} disabled={isLoading}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={handleConnect}
            disabled={connectedLayers.length === 0 || isLoading}
          >
            {isLoading ? <CircularProgress size={24} /> : "Connect"}
          </Button>
        </Box>
      </Paper>

      <Snackbar
        open={!!snackbarMessage}
        autoHideDuration={6000}
        onClose={() => setSnackbarMessage("")}
        message={snackbarMessage}
      />
    </div>
  );
};

export default ConnectCard;
