import React, { useEffect, useRef, useState, useCallback } from "react";
import mapboxgl from "mapbox-gl";
import "mapbox-gl/dist/mapbox-gl.css";
import { createPortal } from "react-dom";
import Tooltip from "./Tooltip";
import ColorCodingLogic, { updateMapColors } from "./ColorCodingLogic";
import MapSelectionLogic from "./MapSelectionLogic";
import Snackbar from "@mui/material/Snackbar";
import Button from "@mui/material/Button";
import "../App.css";

mapboxgl.accessToken = process.env.REACT_APP_MAPBOX_TOKEN;

function Map({
  geoJsonData,
  selectedProperty,
  mapRef,
  setSelectedFeatures,
  selectedFeatures,
  config,
  selectedDashboard,
  currentScenario,
  legendMax,
  legendMin,
  selectedIndex,
  colorScale,
  belowMinColor,
  aboveMaxColor,
  tileLayers,
}) {
  // State variables
  const [mapLoaded, setMapLoaded] = useState(false);
  const [firstLayerLoaded, setFirstLayerLoaded] = useState(false);
  const [showSnackbar, setShowSnackbar] = useState(false);
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const [tooltip, setTooltip] = useState({
    x: 0,
    y: 0,
    propertyValues: [],
  });

  // Ref for the map container element
  const mapContainer = useRef(null);

  // ---------------------------
  // 1. Initialize the Mapbox map instance
  // ---------------------------
  useEffect(() => {
    if (!mapRef.current) {
      mapRef.current = new mapboxgl.Map({
        container: mapContainer.current,
        style: "mapbox://styles/kx64/cljdd8xr6003l01qkbxctho6q",
        center: [0, 0],
        zoom: 2,
        attributionControl: false,
        pitchWithRotate: false,
        dragRotate: false,
      });
      mapRef.current.addControl(
        new mapboxgl.AttributionControl({ compact: true }),
        "bottom-right"
      );
      mapRef.current.on("load", () => setMapLoaded(true));
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
      }
    };
  }, [mapRef]);

  // ---------------------------
  // 2. Setup Tile Layers (single or multiple)
  // ---------------------------
  const setupTileLayers = useCallback(() => {
    if (!mapRef.current) return;

    // First, remove any previous tile layers/sources that might conflict.
    const removeLayerAndSource = (id) => {
      if (mapRef.current.getLayer(id)) mapRef.current.removeLayer(id);
      if (mapRef.current.getSource(id)) mapRef.current.removeSource(id);
    };

    // If multiple tile layers are provided via props…
    if (tileLayers && tileLayers.length > 0) {
      tileLayers.forEach((layer, index) => {
        const sourceId = `tile-source-${index}`;
        const layerId = `tile-layer-${index}`;
        const sourceLayerName = layer.sourceLayerName || "your-source-layer";

        removeLayerAndSource(layerId);

        const sourceOptions = {
          type: "vector",
          tiles: [layer.tileTemplate],
          minzoom: layer.minZoom,
          maxzoom: layer.maxZoom,
        };
        if (layer.bounds) {
          sourceOptions.bounds = layer.bounds;
        }

        mapRef.current.addSource(sourceId, sourceOptions);
        mapRef.current.addLayer({
          id: layerId,
          type: "fill",
          source: sourceId,
          "source-layer": sourceLayerName,
          paint: {
            "fill-color": "#888888",
            "fill-opacity": 0.5,
          },
        });

        // For the first tile layer, fit bounds if bounds are provided.
        if (index === 0 && layer.bounds) {
          const { west, south, east, north } = layer.bounds;
          mapRef.current.fitBounds(
            [
              [west, south],
              [east, north],
            ],
            {
              padding: 50,
              duration: 3000,
            }
          );
        }
      });
    }
    // Else if a single tile source is provided via geoJsonData…
    else if (geoJsonData && geoJsonData.tileSource) {
      const tileSourceId = "tile-source";
      const tileLayerId = "tile-layer";
      const sourceLayerName = "all";
      removeLayerAndSource(tileLayerId);

      const sourceOptions = {
        type: "vector",
        tiles: geoJsonData.tileSource.tiles,
        minzoom: geoJsonData.tileSource.minzoom,
        maxzoom: geoJsonData.tileSource.maxzoom,
      };
      if (geoJsonData.tileSource.bounds) {
        sourceOptions.bounds = geoJsonData.tileSource.bounds;
      }
      mapRef.current.addSource(tileSourceId, sourceOptions);
      mapRef.current.addLayer({
        id: tileLayerId,
        type: "fill",
        source: tileSourceId,
        "source-layer": sourceLayerName,
        paint: {
          "fill-color": "#888888",
          "fill-opacity": 0.5,
        },
      });

      if (geoJsonData.tileSource.bounds) {
        const [west, south, east, north] = geoJsonData.tileSource.bounds;
        const bounds = [
          [west, south],
          [east, north],
        ];
        // Wait until the source data is loaded before fitting bounds.
        mapRef.current.once("sourcedata", (e) => {
          if (e.isSourceLoaded) {
            mapRef.current.fitBounds(bounds, {
              padding: 50,
              maxZoom: 16,
              duration: 3000,
            });
          }
        });
      }
    }
    // Otherwise, if no tile source is provided, clean up any stray layers/sources.
    else {
      removeLayerAndSource("tile-layer");
      removeLayerAndSource("tile-source");
    }
  }, [geoJsonData, tileLayers, mapRef]);

  useEffect(() => {
    if (!mapRef.current || !mapLoaded) return;
    setupTileLayers();

    // If you need any additional click handlers on the tile layers, you can add them here.
    // (Remember to clean them up in the return function below.)
    // For example:
    const handleTileClick = (e) => {
      // Placeholder for feature click logic on tile layers.
      const features = mapRef.current.queryRenderedFeatures(e.point, {
        // For tile layers you might want to query the same layers used for rendering.
        layers: getTooltipLayerIds(),
      });
      // (Implement feature–selection logic if needed.)
    };
    mapRef.current.on("click", handleTileClick);
    return () => {
      if (mapRef.current) mapRef.current.off("click", handleTileClick);
    };
  }, [setupTileLayers, mapLoaded, mapRef]);

  // ---------------------------
  // 3. Setup Tooltip Interactions for Both GeoJSON and MVT Layers
  // ---------------------------
  // Helper: get the layer IDs where tooltips should be active.
  const getTooltipLayerIds = useCallback(() => {
    const ids = [];
    // Always include the GeoJSON layers.
    ids.push("geojson-fill-layer", "geojson-line-layer");
    // Include vector tile layers based on your configuration.
    if (tileLayers && tileLayers.length > 0) {
      tileLayers.forEach((layer, index) => {
        ids.push(`tile-layer-${index}`);
      });
    } else if (geoJsonData && geoJsonData.tileSource) {
      ids.push("tile-layer");
    }
    return ids;
  }, [tileLayers, geoJsonData]);

  useEffect(() => {
    if (!mapRef.current) return;

    const showTooltip = (e) => {
      // Query features from all layers that should trigger tooltips.
      const features = mapRef.current.queryRenderedFeatures(e.point, {
        layers: getTooltipLayerIds(),
      });
      if (!features.length) return;

      // Use the first feature to build tooltip content.
      const feature = features[0];
      const propertyConfig = config[selectedDashboard]?.tooltipProperties || [];
      const propertyValues = propertyConfig.map((p) => ({
        property: p,
        value: feature.properties?.[p] ?? "N/A",
      }));

      // Position the tooltip within the viewport.
      setTooltip({
        x: Math.min(e.point.x, window.innerWidth - 200),
        y: Math.min(e.point.y, window.innerHeight - 100),
        propertyValues,
      });
      setTooltipOpen(true);
    };

    // For desktop: show tooltip on Alt+click.
    const handleDesktopAltClick = (e) => {
      if (e.originalEvent.altKey) {
        showTooltip(e);
      }
    };

    // For mobile: use a long–press (touchstart/touchend) gesture.
    let pressTimerId = null;
    const handleTouchStart = (e) => {
      pressTimerId = setTimeout(() => {
        showTooltip(e);
      }, 500);
    };
    const handleTouchEnd = () => {
      clearTimeout(pressTimerId);
    };

    // Hide tooltip when clicking elsewhere.
    const handleMapClick = () => {
      if (tooltipOpen) {
        setTooltip({ x: 0, y: 0, propertyValues: [] });
        setTooltipOpen(false);
      }
    };

    // Attach the events.
    mapRef.current.on("click", handleDesktopAltClick);
    mapRef.current.on("touchstart", handleTouchStart);
    mapRef.current.on("touchend", handleTouchEnd);
    mapRef.current.on("click", handleMapClick);

    // Cleanup event listeners on unmount.
    return () => {
      if (!mapRef.current) return;
      mapRef.current.off("click", handleDesktopAltClick);
      mapRef.current.off("touchstart", handleTouchStart);
      mapRef.current.off("touchend", handleTouchEnd);
      mapRef.current.off("click", handleMapClick);
    };
  }, [getTooltipLayerIds, config, selectedDashboard, tooltipOpen, mapRef]);

  // ---------------------------
  // 4. Update GeoJSON Source, Fit Bounds, and Color Coding
  // ---------------------------
  useEffect(() => {
    if (!mapRef.current || !geoJsonData) return;

    const updateGeoJsonData = () => {
      const featuresToShow =
        selectedFeatures && selectedFeatures.length > 0
          ? selectedFeatures
          : geoJsonData.features;

      // If the source exists, update its data; otherwise create it.
      let source = mapRef.current.getSource("geojson-source");
      if (source) {
        source.setData({
          type: "FeatureCollection",
          features: featuresToShow,
        });
      } else {
        mapRef.current.addSource("geojson-source", {
          type: "geojson",
          data: {
            type: "FeatureCollection",
            features: featuresToShow,
          },
        });

        // Add a fill layer for polygons.
        mapRef.current.addLayer({
          id: "geojson-fill-layer",
          type: "fill",
          source: "geojson-source",
          filter: [
            "any",
            ["==", ["geometry-type"], "Polygon"],
            ["==", ["geometry-type"], "MultiPolygon"],
          ],
          paint: {
            "fill-color": "#D3D3D3",
            "fill-opacity": 0.7,
          },
        });

        // Add a line layer for lines.
        mapRef.current.addLayer({
          id: "geojson-line-layer",
          type: "line",
          source: "geojson-source",
          filter: [
            "any",
            ["==", ["geometry-type"], "LineString"],
            ["==", ["geometry-type"], "MultiLineString"],
          ],
          paint: {
            "line-color": "#D3D3D3",
            "line-width": 2,
          },
        });
      }

      // Compute bounds from features.
      const bounds = new mapboxgl.LngLatBounds();
      featuresToShow.forEach((feature) => {
        if (!feature || !feature.geometry || !feature.geometry.type) return;
        const coords = feature.geometry.coordinates;
        if (feature.geometry.type === "Point") {
          bounds.extend(coords);
        } else if (["LineString", "MultiPoint"].includes(feature.geometry.type)) {
          coords.forEach((coord) => bounds.extend(coord));
        } else if (["Polygon", "MultiLineString"].includes(feature.geometry.type)) {
          coords.forEach((ring) => ring.forEach((coord) => bounds.extend(coord)));
        } else if (feature.geometry.type === "MultiPolygon") {
          coords.forEach((polygon) =>
            polygon.forEach((ring) => ring.forEach((coord) => bounds.extend(coord)))
          );
        }
      });

      if (!bounds.isEmpty() && !firstLayerLoaded) {
        mapRef.current.fitBounds(bounds, { padding: 20 });
        setFirstLayerLoaded(true);

        // Update the colors on the geojson layer.
        // In the future you could extend updateMapColors to loop over MVT tile layers too.
        updateMapColors(
          mapRef.current,
          selectedProperty,
          config[selectedDashboard],
          legendMax,
          legendMin,
          "initialLoad",
          selectedIndex,
          colorScale,
          belowMinColor,
          aboveMaxColor
        );
      } else if (bounds.isEmpty()) {
        console.warn("No valid features found to fit bounds.");
      } else {
        setShowSnackbar(true);
      }
    };

    if (mapLoaded) {
      updateGeoJsonData();
    } else {
      mapRef.current.on("load", updateGeoJsonData);
      return () => {
        if (mapRef.current) {
          mapRef.current.off("load", updateGeoJsonData);
        }
      };
    }
  }, [
    geoJsonData,
    selectedFeatures,
    mapRef,
    mapLoaded,
    selectedProperty,
    config,
    selectedDashboard,
    legendMax,
    legendMin,
    firstLayerLoaded,
    colorScale,
    belowMinColor,
    aboveMaxColor,
    selectedIndex,
  ]);

  // ---------------------------
  // 5. Handler to Zoom to Data Bounds (invoked via Snackbar action)
  // ---------------------------
  const handleZoomToData = () => {
    if (!geoJsonData || !geoJsonData.features) return;
    const bounds = new mapboxgl.LngLatBounds();
    geoJsonData.features.forEach((feature) => {
      if (!feature || !feature.geometry) return;
      const coords = feature.geometry.coordinates;
      if (feature.geometry.type === "Point") {
        bounds.extend(coords);
      } else if (["LineString", "MultiPoint"].includes(feature.geometry.type)) {
        coords.forEach((coord) => bounds.extend(coord));
      } else if (["Polygon", "MultiLineString"].includes(feature.geometry.type)) {
        coords.forEach((ring) => ring.forEach((coord) => bounds.extend(coord)));
      } else if (feature.geometry.type === "MultiPolygon") {
        coords.forEach((polygon) =>
          polygon.forEach((ring) => ring.forEach((coord) => bounds.extend(coord)))
        );
      }
    });
    if (!bounds.isEmpty()) {
      mapRef.current.fitBounds(bounds, { padding: 20 });
      setShowSnackbar(false);
    }
  };

  // ---------------------------
  // 6. Render
  // ---------------------------
  return (
    <div
      ref={mapContainer}
      className="map-container"
      style={{ height: "100%", width: "100%", position: "relative" }}
    >
      {/* Portal the Tooltip into the map container */}
      {mapContainer.current &&
        createPortal(
          <Tooltip
            x={tooltip.x}
            y={tooltip.y}
            propertyValues={tooltip.propertyValues}
          />,
          mapContainer.current
        )}
      {/* Map selection logic, if any */}
      {mapContainer.current && (
        <MapSelectionLogic
          mapRef={mapRef}
          geoJsonData={geoJsonData}
          setSelectedFeatures={setSelectedFeatures}
          selectedFeatures={selectedFeatures}
          selectionBoxParent={mapContainer.current}
          selectedDashboard={selectedDashboard}
          currentScenario={currentScenario}
        />
      )}
      {/* Color coding logic for the geoJSON layer – extend this later to include MVT layers */}
      {mapLoaded && (
        <ColorCodingLogic
          map={mapRef.current}
          selectedProperty={selectedProperty}
          propertyConfig={config[selectedDashboard]}
          legendMax={legendMax}
          legendMin={legendMin}
          selectedIndex={selectedIndex}
          colorScale={colorScale}
          belowMinColor={belowMinColor}
          aboveMaxColor={aboveMaxColor}
        />
      )}
      {/* Snackbar to prompt a zoom-to-data action */}
      <Snackbar
        open={showSnackbar}
        message="Zoom to data?"
        action={
          <Button color="primary" size="small" onClick={handleZoomToData}>
            Zoom to Data
          </Button>
        }
        onClose={() => setShowSnackbar(false)}
        autoHideDuration={6000}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      />
    </div>
  );
}

export default React.memo(Map);
