import React, { useState, useRef, useEffect } from "react";
import { FileUploadLogic } from "./FileUploadLogic";
import {
  Typography,
  Button,
  Box,
  List,
  ListItem,
  ListItemText,
  Paper,
  IconButton,
  Snackbar,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import CircularProgress from "@mui/material/CircularProgress";
import LinearProgress from "@mui/material/LinearProgress";
import Overlay from "./Overlay";
import * as utilities from "./Utilities";
import DemoFileSelector from "./DemoFileSelector";
import { useLocation } from "react-router-dom";
import { RouteLoader } from "./RouteLoader";
import { calculatePropertySums } from "./Utilities";
import ConnectCard from "./ConnectCard"; // Import your new ConnectCard component

function FileUploadCard({
  showFileUploadCard,
  isAppInitialized,
  setIsAppInitialized,
  fileList,
  setFileList,
  setGeoJsonFilesByDashboard,
  setInitialSelection,
  onClose,
  config,
  setConfig,
  setScenarioData,
  canClose,
  setCanClose,
  setTileLayers,
}) {
  const [errorMessage, setErrorMessage] = useState("");
  const [showSnackbar, setShowSnackbar] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [fileProgress, setFileProgress] = useState({});
  const [removedFiles, setRemovedFiles] = useState([]);
  const fileInputElement = useRef(null);
  const [showDemoSelector, setShowDemoSelector] = useState(false);
  const [showConnectCard, setShowConnectCard] = useState(false); // New state for ConnectCard
  const location = useLocation();

  const handleTileServerConnected = (virtualFiles) => {
    // This merges the new “virtual files” into your existing fileList.
    setFileList((prev) => {
      // If you want to avoid duplicates, you can also filter
      // out any that share the same name.
      const uniqueNew = virtualFiles.filter(
        (vf) => !prev.some((f) => f.name === vf.name)
      );
      return [...prev, ...uniqueNew];
    });
  };

  const handleError = (message) => {
    setErrorMessage(message);
    setShowSnackbar(true);
  };

  const handleFileUpload = (event) => {
    const files = Array.from(event.target.files);
    handleFileProcessing(files);
  };

  const handleFileProcessing = async (files) => {
    const validFiles = [];
    const invalidFiles = [];
    const duplicateFiles = [];

    for (const file of files) {
      if (file.name.endsWith(".geojson")) {
        if (fileList.some((f) => f.name === file.name)) {
          duplicateFiles.push(file.name);
        } else if (file.size > 75000000000) {
          invalidFiles.push(`${file.name} (File too large)`);
        } else {
          validFiles.push(file);
        }
      } else if (file.name.endsWith(".csv")) {
        try {
          const geoJson = await utilities.convertCsvToGeoJson(file);
          const geoJsonFile = new File(
            [JSON.stringify(geoJson)],
            `${file.name.replace(".csv", ".geojson")}`,
            { type: "application/geo+json" }
          );
          if (fileList.some((f) => f.name === geoJsonFile.name)) {
            duplicateFiles.push(file.name);
          } else {
            validFiles.push(geoJsonFile);
          }
        } catch (error) {
          invalidFiles.push(`${file.name} (${error})`);
        }
      } else {
        invalidFiles.push(`${file.name} (Unsupported file type)`);
      }
    }

    if (invalidFiles.length > 0) {
      handleError(
        `The following files are invalid:\n${invalidFiles.join("\n")}`
      );
    }

    if (duplicateFiles.length > 0) {
      handleError(
        `The following files are duplicates and were not added:\n${duplicateFiles.join(
          "\n"
        )}`
      );
    }

    if (validFiles.length > 0) {
      setFileList((prevFileList) => [...prevFileList, ...validFiles]);
      setIsAppInitialized(true);
    }
  };

  const handleUploadButtonClick = () => {
    if (fileInputElement.current) {
      fileInputElement.current.click();
    }
  };

  const handleViewClick = async () => {
    if (fileList.length === 0 && removedFiles.length > 0) {
      setFileList(removedFiles);
      setRemovedFiles([]);
      return;
    }

    setIsLoading(true);
    try {
      const dashboards = await FileUploadLogic(
        fileList,
        config,
        setConfig,
        setFileProgress
      );
      setGeoJsonFilesByDashboard(dashboards);

      const firstDashboard = Object.keys(dashboards)[0];
      const firstScenario = dashboards[firstDashboard][0].data;

      const initialSelectedProperty =
        config[firstDashboard]?.selectedProperty ||
        config["DataDashboard"]?.selectedProperty ||
        config["DataDashboard"]?.properties[0]?.name;

      setInitialSelection({
        dashboard: firstDashboard,
        scenario: firstScenario,
        selectedProperty: initialSelectedProperty,
      });

      const scenarioSums = utilities.calculatePropertySums(dashboards);
      setScenarioData(scenarioSums);

      setCanClose(true);
      onClose();
      setRemovedFiles([]);
    } catch (error) {
      handleError(`Error processing files: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  // In the same file where getDemoFiles is defined
  const getDemoFiles = (config) => {
    // First check if config and DemoData exist
    if (!config?.DemoData) {
      return []; // Return empty array if no demo data
    }

    return Object.values(config.DemoData).map((demoConfig) => ({
      filename: demoConfig.filename,
      displayName: demoConfig.displayName,
      thumbnail: demoConfig.thumbnail,
      slug: demoConfig.slug,
    }));
  };

  const handleRemoveFile = (index) => {
    const removedFile = fileList[index];
    setRemovedFiles((prevRemovedFiles) => [...prevRemovedFiles, removedFile]);

    const newFileList = fileList.filter((_, i) => i !== index);
    setFileList(newFileList);

    if (newFileList.length === 0) {
      if (canClose) {
        setErrorMessage("Please upload files to edit file list.");
        setShowSnackbar(true);
        return;
      } else {
        setIsAppInitialized(false);
      }
      setCanClose(false);
      return;
    }

    setGeoJsonFilesByDashboard((prevGeoJsonFiles) => {
      const newGeoJsonFiles = { ...prevGeoJsonFiles };
      for (const dashboard in newGeoJsonFiles) {
        newGeoJsonFiles[dashboard] = newGeoJsonFiles[dashboard].filter(
          (fileData) => fileData.name !== removedFile.name
        );

        if (newGeoJsonFiles[dashboard].length === 0) {
          delete newGeoJsonFiles[dashboard];
        }
      }
      return newGeoJsonFiles;
    });

    setScenarioData((prevScenarioData) => {
      const newScenarioData = { ...prevScenarioData };
      for (const scenario in newScenarioData) {
        if (scenario.includes(removedFile.name)) {
          delete newScenarioData[scenario];
        }
      }
      return newScenarioData;
    });
  };

  const loadDemoData = async (file) => {
    setIsLoading(true);
    try {
      handleFileProcessing([file]);
    } catch (error) {
      handleError(`Error loading demo data: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const loadDataFromUrl = async () => {
      const routeSlug = location.pathname.slice(1);
      if (!routeSlug) return;

      setIsLoading(true);
      try {
        const files = await RouteLoader.loadRoute(routeSlug);
        setFileList(files);
        setIsAppInitialized(true);

        const dashboards = await FileUploadLogic(
          files,
          config,
          setConfig,
          setFileProgress
        );

        setGeoJsonFilesByDashboard(dashboards);

        const firstDashboard = Object.keys(dashboards)[0];
        const firstScenario = dashboards[firstDashboard][0].data;

        setInitialSelection({
          dashboard: firstDashboard,
          scenario: firstScenario,
          selectedProperty: config[firstDashboard]?.selectedProperty,
        });

        const scenarioSums = calculatePropertySums(dashboards);
        setScenarioData(scenarioSums);

        setCanClose(true);
        onClose();
      } catch (error) {
        console.error("Error loading data from URL:", error);
        setErrorMessage(`Error loading data: ${error.message}`);
        setShowSnackbar(true);
      } finally {
        setIsLoading(false);
      }
    };

    loadDataFromUrl();
  }, [location.pathname]);

  return (
    <div>
      <Snackbar
        open={showSnackbar}
        autoHideDuration={6000}
        onClose={() => setShowSnackbar(false)}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Alert
          onClose={() => setShowSnackbar(false)}
          severity="error"
          sx={{ width: "100%" }}
        >
          {errorMessage}
        </Alert>
      </Snackbar>

      {!isAppInitialized ? (
        <div
          style={{
            position: "fixed",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            textAlign: "center",
            width: "100%",
            maxWidth: "500px",
            padding: "20px",
            zIndex: 1000,
          }}
        >
          <img
            src={`${process.env.PUBLIC_URL}/Urbano-Viewer-Logo.png`}
            alt="Urbano Viewer"
            style={{
              width: "100%",
              maxWidth: "500px",
              height: "auto",
              padding: "10px",
            }}
          />
          <Box margin={2} display={"flex"} gap={2} justifyContent={"center"}>
            <input
              accept=".csv,.geojson,application/json"
              style={{ display: "none" }}
              id="upload-file"
              type="file"
              multiple
              onChange={handleFileUpload}
              ref={fileInputElement}
            />
            <Button
              variant="contained"
              color="primary"
              onClick={handleUploadButtonClick}
              disabled={isLoading}
            >
              Upload
            </Button>
            {/* New Connect button */}
            <Button
              variant="contained"
              color="secondary"
              onClick={() => setShowConnectCard(true)}
              disabled={isLoading}
            >
              Connect
            </Button>
          </Box>
          <Typography
            variant="body2"
            onClick={() => setShowDemoSelector(true)}
            style={{
              color: "grey",
              textDecoration: "underline",
              cursor: "pointer",
              margin: "10px 0",
            }}
          >
            preview demo data
          </Typography>
          <DemoFileSelector
            open={showDemoSelector}
            onClose={() => setShowDemoSelector(false)}
            onSelectFile={loadDemoData}
            config={config}
          />
          <Typography
            variant="body2"
            style={{ color: "grey", margin: "10px 0" }}
          >
            made in ithaca, ny with ❤️
          </Typography>
          <Typography variant="body2" style={{ color: "grey" }}>
            V 1.15
          </Typography>
        </div>
      ) : (
        showFileUploadCard && (
          <div>
            <Overlay />
            <Paper
              elevation={3}
              style={{
                padding: "16px",
                display: "flex",
                flexDirection: "column",
                position: "fixed",
                top: "50%",
                left: "50%",
                transform: "translate(-50%, -50%)",
                width: "90%",
                maxWidth: "500px",
                maxHeight: "90vh",
                zIndex: 1000,
              }}
            >
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
                mb={2}
              >
                <Typography variant="h6">File Upload</Typography>
                {canClose && (
                  <IconButton onClick={onClose}>
                    <CloseIcon />
                  </IconButton>
                )}
              </Box>

              <Typography variant="body2" mb={2}>
                Manage GeoJSON files here
              </Typography>

              <Box
                sx={{
                  flex: 1,
                  overflowY: "auto",
                  minHeight: "100px",
                  maxHeight: "calc(90vh - 200px)",
                }}
              >
                <List>
                  {fileList.map((file, index) => (
                    <ListItem
                      key={index}
                      sx={{
                        display: "block",
                        py: 1,
                        "&:hover": {
                          backgroundColor: "rgba(0, 0, 0, 0.04)",
                        },
                      }}
                    >
                      <Box sx={{ display: "flex", alignItems: "center" }}>
                        <IconButton
                          size="small"
                          onClick={() => handleRemoveFile(index)}
                          disabled={isLoading}
                        >
                          <CloseIcon />
                        </IconButton>
                        <ListItemText
                          primary={utilities.truncateFileName(file.name)}
                        />
                      </Box>
                      <Box sx={{ width: "100%", mt: 1 }}>
                        <LinearProgress
                          variant="determinate"
                          value={fileProgress[file.name] || 0}
                          sx={{ bgcolor: "lightgrey" }}
                        />
                      </Box>
                    </ListItem>
                  ))}
                </List>
              </Box>

              <Box
                display="flex"
                justifyContent="flex-end"
                gap={2}
                mt={2}
                sx={{
                  position: "sticky",
                  bottom: 0,
                  backgroundColor: "white",
                  pt: 2,
                }}
              >
                <input
                  accept=".geojson,application/json"
                  style={{ display: "none" }}
                  id="upload-file"
                  type="file"
                  multiple
                  onChange={handleFileUpload}
                  ref={fileInputElement}
                />
                <Button
                  variant="contained"
                  color="primary"
                  onClick={handleUploadButtonClick}
                  disabled={isLoading}
                >
                  Upload
                </Button>
                <Button
                  variant="contained"
                  color="primary"
                  onClick={handleViewClick}
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <CircularProgress size={24} color="inherit" />
                  ) : (
                    "OK"
                  )}
                </Button>
              </Box>
            </Paper>
          </div>
        )
      )}

      {/* Render ConnectCard when showConnectCard is true */}
      {showConnectCard && (
        <ConnectCard
          onClose={() => {
            setShowConnectCard(false);
            onClose();
          }}
          setGeoJsonFilesByDashboard={setGeoJsonFilesByDashboard}
          setInitialSelection={setInitialSelection}
          setIsAppInitialized={setIsAppInitialized}
          config={config}
          setTileLayers={setTileLayers}
          setConfig={setConfig}
          setScenarioData={setScenarioData}
          onTileServerConnected={handleTileServerConnected}
        />
      )}
    </div>
  );
}

export default FileUploadCard;
