import React, { useState, useEffect } from "react";
import {
  Card,
  CardContent,
  Button,
  Typography,
  Snackbar,
  IconButton,
  Box,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import RestoreIcon from "@mui/icons-material/Restore";
import DownloadIcon from "@mui/icons-material/Download";
import SaveIcon from "@mui/icons-material/Save";
import Overlay from "./Overlay";
import Editor from "@monaco-editor/react";
import dashboardConfig from "./DashboardConfig"; // Import from DashboardConfig.jsx instead of directly from JSON

const DashboardConfigEditor = ({ onSave, onClose }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery("(max-width:900px)");
  const isTablet = useMediaQuery("(max-width:1024px)");

  const localStorageKey = "dashboardConfig";
  const [configText, setConfigText] = useState("");

  const [error, setError] = useState(null);
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");  // Add this line

  // Use the imported dashboardConfig as default
  useEffect(() => {
    const savedConfig = localStorage.getItem(localStorageKey);
    if (savedConfig) {
      try {
        const parsedConfig = JSON.parse(savedConfig);
        setConfigText(JSON.stringify(parsedConfig, null, 2));
      } catch (e) {
        console.error("Error parsing saved config:", e);
        handleRestoreDefault();
      }
    } else {
      handleRestoreDefault();
    }
  }, []);

  const handleEditorChange = (value, event) => {
    setConfigText(value);
  };

  const handleSave = () => {
    try {
      const updatedConfig = JSON.parse(configText);
      localStorage.setItem(localStorageKey, configText);
      onSave(updatedConfig);
      setError(null);
      setSnackbarOpen(true);
    } catch (e) {
      setError("Invalid JSON format");
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  const handleRestoreDefault = () => {
    try {
      // Use the imported dashboardConfig
      const defaultConfigString = JSON.stringify(dashboardConfig, null, 2);
      setConfigText(defaultConfigString);
      localStorage.setItem(localStorageKey, defaultConfigString);
      onSave(dashboardConfig);
      setError(null);
      setSnackbarMessage("Default configuration restored!");
      setSnackbarOpen(true);
    } catch (e) {
      console.error("Error restoring default config:", e);
      setSnackbarMessage("Error restoring default configuration");
      setSnackbarOpen(true);
    }
  };

  const handleDownload = () => {
    const element = document.createElement("a");
    const file = new Blob([configText], { type: "application/json" });
    element.href = URL.createObjectURL(file);
    element.download = "dashboardConfig.json";
    document.body.appendChild(element);
    element.click();
    element.remove();
  };

  return (
    <div>
      <Overlay />
      <Card
        elevation={3}
        className="dashboard-config-editor"
        sx={{
          padding: isMobile ? "10px" : "20px",
          display: "flex",
          flexDirection: "column",
          position: "absolute",
          width: isMobile ? "95%" : isTablet ? "90%" : "50%",
          height: isMobile ? "90%" : "80%",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          zIndex: 1000,
        }}
      >
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          sx={{ mb: isMobile ? 1 : 2 }}
        >
          <Typography
            variant={isMobile ? "h6" : "h5"}
            component="div"
            sx={{
              fontSize: isMobile ? "1rem" : undefined,
              marginRight: isMobile ? "8px" : undefined,
            }}
          >
            Dashboard Configuration
          </Typography>
          <IconButton onClick={onClose} size={isMobile ? "small" : "medium"}>
            <CloseIcon />
          </IconButton>
        </Box>

        <CardContent
          sx={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
            margin: isMobile ? "5px" : "20px",
            padding: isMobile ? "8px !important" : "16px !important",
            border: "1px solid #ccc",
          }}
        >
          <div style={{ flex: 1, position: "relative" }}>
            <Editor
              height="100%"
              defaultLanguage="json"
              value={configText}
              onChange={handleEditorChange}
              options={{
                minimap: { enabled: !isMobile },
                wordWrap: "on",
                automaticLayout: true,
                scrollBeyondLastLine: false,
                folding: true,
                lineNumbers: isMobile ? "off" : "on",
                fontSize: isMobile ? 12 : 14,
              }}
            />
          </div>
          {error && (
            <Typography
              color="error"
              variant="body2"
              sx={{
                mt: 1,
                fontSize: isMobile ? "0.75rem" : undefined,
              }}
            >
              {error}
            </Typography>
          )}
        </CardContent>

        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            flexDirection: isMobile ? "column" : "row",
            gap: isMobile ? 1 : 2,
            mt: isMobile ? 1 : 2,
          }}
        >
          <Button
            variant="contained"
            color="secondary"
            onClick={handleRestoreDefault}
            startIcon={<RestoreIcon />}
            size={isMobile ? "small" : "medium"}
            fullWidth={isMobile}
          >
            {isMobile ? "Restore" : "Restore Default"}
          </Button>
          <Button
            variant="contained"
            color="primary"
            onClick={handleDownload}
            startIcon={<DownloadIcon />}
            size={isMobile ? "small" : "medium"}
            fullWidth={isMobile}
          >
            {isMobile ? "Download" : "Download Config"}
          </Button>
          <Button
            variant="contained"
            color="primary"
            onClick={handleSave}
            startIcon={<SaveIcon />}
            size={isMobile ? "small" : "medium"}
            fullWidth={isMobile}
          >
            {isMobile ? "Save" : "Save Configuration"}
          </Button>
        </Box>
      </Card>

      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        message="Configuration saved successfully!"
        sx={{
          "& .MuiSnackbarContent-root": {
            fontSize: isMobile ? "0.875rem" : undefined,
          },
        }}
      />
    </div>
  );
};

export default DashboardConfigEditor;
