import React from 'react';
import { 
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Typography,
  Box
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';

// Helper function to get demo files from dashboard config
const getDemoFilesFromConfig = (config) => {
  if (!config?.DemoData) {
    return [];
  }
  
  return Object.values(config.DemoData).map(demoConfig => ({
    filename: demoConfig.filename,
    displayName: demoConfig.displayName,
    thumbnail: `${process.env.PUBLIC_URL}${demoConfig.thumbnail}`,
    slug: demoConfig.slug,
    path: demoConfig.path
  }));
};

const DemoFileSelector = ({ open, onClose, onSelectFile, config }) => {
  const demoFiles = getDemoFilesFromConfig(config);

  const handleFileSelect = async (filename) => {
    try {
      const response = await fetch(`${process.env.PUBLIC_URL}/demoData/${filename}`);
      if (!response.ok) {
        throw new Error(`Failed to load demo data: ${filename}`);
      }
      const demoBlob = await response.blob();
      const file = new File([demoBlob], filename, {
        type: "application/geo+json",
      });
      onSelectFile(file);
      onClose();
    } catch (error) {
      console.error(`Error loading demo file: ${error.message}`);
    }
  };

  // If no demo files are available, don't render anything
  if (!demoFiles.length) {
    return null;
  }

  return (
    <Dialog 
      open={open} 
      onClose={onClose}
      maxWidth="md"
      fullWidth
    >
      <DialogTitle>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h6">Select Demo Data</Typography>
          <IconButton onClick={onClose} size="small">
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>
      <DialogContent>
        <Grid container spacing={3} padding={2}>
          {demoFiles.map((demo) => (
            <Grid item xs={12} sm={6} key={demo.slug}>
              <Card 
                sx={{ 
                  cursor: 'pointer',
                  '&:hover': {
                    boxShadow: 6,
                    transform: 'scale(1.02)',
                    transition: 'all 0.2s ease-in-out'
                  }
                }}
                onClick={() => handleFileSelect(demo.filename)}
              >
                <CardMedia
                  component="img"
                  height="140"
                  image={demo.thumbnail}
                  alt={demo.displayName}
                  sx={{ objectFit: 'cover' }}
                />
                <CardContent>
                  <Typography variant="h6" component="div">
                    {demo.displayName}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </DialogContent>
    </Dialog>
  );
};

export default DemoFileSelector;