// routeLoader.js
import dashboardConfig from './DashboardConfig';

export class RouteLoader {
  static async loadDemoRoute(routeSlug) {
    const demoConfig = dashboardConfig.DemoData || {};
    
    const routeConfig = demoConfig[routeSlug];
    if (!routeConfig) {
      throw new Error(`No demo configuration found for route: ${routeSlug}`);
    }

    const files = await Promise.all([{
      filename: routeConfig.filename,
      path: routeConfig.path
    }].map(async (fileConfig) => {
      const response = await fetch(`${process.env.PUBLIC_URL}${fileConfig.path}`);
      if (!response.ok) {
        throw new Error(`Failed to load file: ${fileConfig.filename}`);
      }
      const blob = await response.blob();
      return new File([blob], fileConfig.filename, { type: 'application/geo+json' });
    }));

    return files;
  }

  static async loadUserRoute(shareId) {
    // This will be implemented later when backend is added
    throw new Error('User routes not yet implemented');
  }

  static async loadRoute(routeSlug) {
    const demoConfig = dashboardConfig.DemoData || {};
    
    // First check if it's a demo route
    if (demoConfig[routeSlug]) {
      return this.loadDemoRoute(routeSlug);
    }

    // If not a demo route, try to load as user route
    try {
      return await this.loadUserRoute(routeSlug);
    } catch (error) {
      if (error.message === 'User routes not yet implemented') {
        throw new Error('Invalid route or route type not supported');
      }
      throw error;
    }
  }
}