import React, { useRef, useState, useEffect } from 'react';

const CardContainer = ({ children, side = 'right', isMobile = false }) => {
  const containerRef = useRef(null);
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => {
      setWindowWidth(window.innerWidth);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Helper to check if child is a valid React element
  const isValidChild = (child) => {
    return React.isValidElement(child) && child !== null;
  };

  // Filter out any null or undefined children
  const validChildren = React.Children.toArray(children).filter(isValidChild);

  if (validChildren.length === 0) {
    return null;
  }

  // Calculate container positioning and width
  const isMobileView = windowWidth <= 430;
  const containerWidth = isMobileView ? 'calc(100% - 10px)' : '420px';
  const containerPosition = isMobileView ? {
    left: '5px',
    right: '5px',
    width: 'auto'
  } : {
    [side]: '5px',
    width: containerWidth
  };

  return (
    <div 
      ref={containerRef}
      className="card-container"
      style={{
        position: 'absolute',
        top: 0,
        bottom: 0,
        ...containerPosition,
        overflowY: 'auto',
        overflowX: 'visible',
        display: 'flex',
        flexDirection: 'column',
        padding: isMobileView ? '10px' : '10px',
        paddingTop: '10px',
        paddingBottom: '20px',
        zIndex: 1000,
        pointerEvents: 'none',
        scrollbarWidth: 'none',
        msOverflowStyle: 'none',
        '&::-webkit-scrollbar': {
          display: 'none'
        }
      }}
    >
      {validChildren.map((child, index) => (
        <div 
          key={index}
          style={{ 
            pointerEvents: 'auto',
            width: '100%'
          }}
        >
          {React.cloneElement(child, {
            onCollapsedChange: (isCollapsed) => {
              // Callback logic here if needed
            },
            isMobileView,
            containerWidth: isMobileView ? windowWidth - 20 : 400 // Pass window width to child
          })}
        </div>
      ))}
    </div>
  );
};

export default CardContainer;