import * as d3 from 'd3';

export const renderEnergyAnnualEndUseGraph = (chartRef, selectedFeatures, dashboardConfig) => {
  if (!Array.isArray(selectedFeatures)) {
    console.error("selectedFeatures is not an array:", selectedFeatures);
    return;
  }

  const filteredFeatures = selectedFeatures.filter(
    (feature) => feature.geometry?.type !== 'Point'
  );

  const energyCategories = [
    "gasEquipment",
    "equipment",
    "lighting",
    "hotWater",
    "auxiliary",
    "cooling",
    "heating",
    "PV"
  ];

  // Initialize annualData with zero values for all categories
  const annualData = Object.fromEntries(energyCategories.map(category => [category, 0]));

  // Accumulate data from selected features
  filteredFeatures.forEach((feature) => {
    energyCategories.forEach((category) => {
      const propertyKey = {
        gasEquipment: "GasEquipment[KWh][Yr]",
        equipment: "Equipment[KWh][Yr]",
        lighting: "Lighting[KWh][Yr]",
        hotWater: "HotWater[KWh][Yr]",
        auxiliary: "Auxiliary[KWh][Yr]",
        cooling: "Cooling[KWh][Yr]",
        heating: "Heating[KWh][Yr]",
        PV: "PV[KWh][Yr]",
      }[category];

      annualData[category] += feature.properties?.[propertyKey] || 0;
    });
  });

  // Separate PV from the stacked categories
  const pvData = annualData.PV;
  delete annualData.PV;

  const nonPvTotalEnergyUse = d3.sum(Object.values(annualData));
  const totalEnergyUse = pvData + nonPvTotalEnergyUse;

  // Maintain consistent order while filtering out empty categories
  const keys = energyCategories.filter(category => category !== "PV" && annualData[category] > 0);

  if (!keys.length) {
    console.error("No valid keys found for annualData:", annualData);
    return;
  }

  const margin = { top: 20, right: 40, bottom: 90, left: 20 };
  const width = (dashboardConfig?.chartSettings?.width || 700) / 2 - margin.left - margin.right;
  const height = dashboardConfig?.chartSettings?.height || 70;

  const svg = d3.select(chartRef.current)
    .append('svg')
    .attr('width', width + margin.left + margin.right)
    .attr('height', height * 2 + margin.top + margin.bottom)
    .append('g')
    .attr('transform', `translate(${margin.left},${margin.top})`);

  const pvBarHeight = height / 2;
  const pvScale = d3.scaleLinear()
    .domain([0, totalEnergyUse])
    .range([0, width]);

  svg.append('rect')
    .attr('x', 0)
    .attr('y', 0)
    .attr('height', pvBarHeight)
    .attr('width', pvScale(pvData))
    .attr('fill', '#9C27B0'); // PV Color

  svg.append('text')
    .attr('x', pvScale(pvData) + 5)
    .attr('y', pvBarHeight / 2)
    .attr('dy', '.35em')
    .style('font-size', '12px')
    .style('fill', '#000')
    .text(`${d3.format('.2s')(pvData)} `);

  const x = d3.scaleLinear()
    .domain([0, totalEnergyUse])
    .nice()
    .range([0, width]);

  const y = d3.scaleBand()
    .range([pvBarHeight + 10, pvBarHeight + height])
    .padding(0.1);

  // Use the same fixed color order
  const colorScale = d3.scaleOrdinal()
    .domain(energyCategories) // Maintain fixed order
    .range(['#D28066', '#959595', '#F2E75C', '#EEC176', '#B087D6', '#6FAADD', '#CF5867', '#9C27B0']);

  let accumulatedValue = 0;

  svg.selectAll('rect.stack')
    .data(keys)
    .enter().append('rect')
    .attr('class', 'stack')
    .attr('x', (d) => {
      const xValue = accumulatedValue;
      accumulatedValue += annualData[d];
      return x(xValue);
    })
    .attr('y', pvBarHeight + 10)
    .attr('height', y.bandwidth())
    .attr('width', d => x(annualData[d]) - x(0))
    .attr('fill', d => colorScale(d));

  svg.append('text')
    .attr('x', x(nonPvTotalEnergyUse) + 5)
    .attr('y', pvBarHeight + 10 + y.bandwidth() / 2)
    .attr('dy', '.35em')
    .style('font-size', '12px')
    .style('fill', '#000')
    .text(`${d3.format('.2s')(nonPvTotalEnergyUse)} `);

  const legend = svg.append('g')
    .attr('transform', `translate(0, ${pvBarHeight + height + 30})`);

  // Maintain consistent legend order
  const legendCategories = energyCategories.filter(category => category in annualData || category === "PV");

  legendCategories.forEach((category, i) => {
    const row = Math.floor(i / 3);
    const col = i % 3;

    legend.append('rect')
      .attr('x', col * 110)
      .attr('y', row * 20)
      .attr('width', 10)
      .attr('height', 10)
      .attr('fill', colorScale(category));

    legend.append('text')
      .attr('x', col * 110 + 20)
      .attr('y', row * 20 + 10)
      .text(category)
      .style('font-size', '12px')
      .style('fill', '#000');
  });
};
